mapper.delete:
DELETE FROM analysis_resource
 WHERE file_id = #{fileId}
   AND resource_type NOT IN ('SERVLET_MAPPING', 'FILTER_MAPPING', 'LISTENER')

DELETE FROM analysis_relation
 WHERE revision_id = #{revisionId}
   AND relation_type IN ('EXECUTES_SQL', 'READS_TABLE', 'WRITES_TABLE')

mapper.select:
SELECT initializer_summary AS "initializer"
  FROM analysis_field
 WHERE revision_id = #{revisionId}
   AND owner_symbol_id = #{symbolId}
   AND name = #{name}
 LIMIT 1

SELECT f.path AS "path", f.encoding AS "encoding", m.line_start AS "lineStart", m.line_end AS "lineEnd"
  FROM analysis_method m
  JOIN analysis_file f ON f.file_id = m.file_id
 WHERE m.revision_id = #{revisionId}
   AND m.owner_symbol_id = #{symbolId}
   AND m.name = #{name}
   AND m.param_count = 0
   AND NOT m.is_synthetic
 LIMIT 1

SELECT r.resource_type AS "resourceType", r.name AS "name", r.value AS "value", r.properties_json::text AS "properties"
     , f.path AS "file", r.line_start AS "lineStart"
  FROM analysis_resource r
  JOIN analysis_file f ON f.file_id = r.file_id
 WHERE r.revision_id = #{revisionId}
AND r.resource_type = #{resourceType}
AND r.name LIKE '%' || #{name} || '%'
 ORDER BY r.resource_type, r.name, r.resource_id
 LIMIT #{size} OFFSET #{offset}
